document.body.innerHTML=`<header><b>${icon('leaf')}宏观基础 <span style="font-size:11px;color:#91a08f;font-weight:400">/ 看见经济的联系</span></b><a href="index.html">投资版</a></header><main class="layout"><div class="intro"><div><h1>从一笔钱，看懂经济如何运转</h1><p>沿着同一个场景，串起货币、利率与通胀。</p></div><span class="tag">连续图解 · 5 个阶段</span></div><div class="workspace"><div><section class="canvas" aria-label="经济运行关系图"><div class="canvas-top"><span><i></i>居民 · 银行 · 企业</span><span>假设场景 / 非实时数据</span></div><div class="map"><svg class="links" viewBox="0 0 700 390" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="m0 0 10 5-10 5" style="fill:#739781;stroke:none"/></marker></defs><path id="path0" d="M290 125 Q140 130 100 245" marker-end="url(#arrow)"/><path id="path1" d="M410 125 Q560 130 605 245" marker-end="url(#arrow)"/><path id="path2" d="M165 307 Q350 355 535 307" marker-end="url(#arrow)"/><text x="65" y="175" id="label0"/><text x="450" y="175" id="label1"/><text x="350" y="366" text-anchor="middle" id="label2"/></svg><div class="entity bank" id="bank">${icon('bank')}<strong>商业银行</strong><small>信贷与结算</small><output></output></div><div class="entity people" id="people">${icon('people')}<strong>居民</strong><small>劳动 · 收入 · 消费</small><output></output></div><div class="entity firm" id="firm">${icon('firm')}<strong>企业</strong><small>融资 · 生产 · 工资</small><output></output></div><div class="center-note"><b id="value"></b><span id="center"></span></div></div></section><div class="controls"><button id="prev" aria-label="上一步">←</button><button class="play" id="play">自动演示</button><span id="position"></span><div class="progress"><i id="progress"></i></div><button id="next">下一步 →</button></div></div><aside class="explain" aria-live="polite"><div class="step-label" id="topic"></div><h2 id="title"></h2><p id="text"></p><div class="mechanism"><b>这一步的关键</b><p id="why"></p></div><div class="legend">沿箭头看资金与影响方向。绿色边框强调当前相关角色；所有金额均为独立教学示例，不是连续会计账簿。</div></aside></div><nav class="steps" aria-label="叙事阶段">${scenes.map((s,i)=>`<button data-step="${i}"><span>0${i+1}</span><b>${s.name}</b><span>${s.topic}</span></button>`).join('')}</nav><details class="details"><summary>深入理解：这张图省略了什么？</summary><p>经济还包括央行、政府和对外部门。利率通过银行与市场影响信贷，也通过预期和汇率影响需求。物价变化取决于供需、成本与预期；新增存款不意味着物价立即、等比例上涨。图中展示基本机制，现实的幅度和时点并不确定。</p><p><a href="money.html">货币详细图解 →</a>　<a href="rates.html">利率详细图解 →</a>　<a href="inflation.html">通胀详细图解 →</a></p></details><footer>宏观基础知识版 · 图形、金额均为教学示例</footer></main>`;
let current=0,timer=null;const $=s=>document.querySelector(s);function show(i){current=i;const s=scenes[i];for(const key of ['topic','title','text','why','center','value'])$('#'+key).textContent=s[key];for(const key of ['bank','people','firm'])$('#'+key+' output').textContent=s[key];for(let j=0;j<3;j++){$('#label'+j).textContent=s.labels[j];$('#path'+j).classList.toggle('on',j===s.active)}document.querySelectorAll('.entity').forEach(e=>e.classList.remove('focus'));$(i===0?'#people':i===1?'#bank':'#firm').classList.add('focus');document.querySelectorAll('[data-step]').forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-current',j===i?'step':'false')});$('#position').textContent=`${i+1} / ${scenes.length}`;$('#progress').style.width=((i+1)/scenes.length*100)+'%';$('#prev').disabled=i===0;$('#next').textContent=i===4?'从头观看 ↻':'下一步 →'}function stop(){clearInterval(timer);timer=null;$('#play').textContent='自动演示'}$('#prev').onclick=()=>{stop();show(Math.max(0,current-1))};$('#next').onclick=()=>{stop();show((current+1)%5)};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{stop();show(+b.dataset.step)});$('#play').onclick=()=>{if(timer){stop();return}$('#play').textContent='暂停演示';timer=setInterval(()=>{if(current===4){stop();return}show(current+1)},9000)};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});show(0);
